// The original image is never resampled by zooming or panning.
sealed class ZoomPicture : PictureBox {
 double zoom; PointF pan; Point dragStart;PointF dragPan;bool dragging;public bool Checkerboard;
 public event EventHandler ViewChanged;
 public double EffectiveZoom {get {return Image==null?1:zoom==0?Math.Min(16,Math.Min((double)Math.Max(1,ClientSize.Width)/Image.Width,(double)Math.Max(1,ClientSize.Height)/Image.Height)):zoom;}}
 public bool IsFit {get{return zoom==0;}}
 public PointF PanOffset {get{return pan;}}
 public ZoomPicture(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);TabStop=true;}
 void Changed(){if(IsDisposed||Disposing)return;Form form=FindForm();if(form!=null&&(form.Disposing||(form is MainForm&&((MainForm)form).IsClosingLayout)))return;Invalidate();if(ViewChanged!=null)ViewChanged(this,EventArgs.Empty);}
 public void Fit(){zoom=0;pan=PointF.Empty;Changed();}
 public void SetZoom(double value){ZoomAt(value,new Point(ClientSize.Width/2,ClientSize.Height/2));}
 public void ZoomAt(double value,Point anchor){double old=EffectiveZoom;double next=Math.Max(.05,Math.Min(16,value));double ratio=next/old;float x=anchor.X-ClientSize.Width/2f,y=anchor.Y-ClientSize.Height/2f;pan=new PointF((float)(x-(x-pan.X)*ratio),(float)(y-(y-pan.Y)*ratio));zoom=next;Changed();}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(BackColor);if(Image==null)return;double factor=EffectiveZoom;float w=(float)(Image.Width*factor),h=(float)(Image.Height*factor);RectangleF rect=new RectangleF((ClientSize.Width-w)/2+pan.X,(ClientSize.Height-h)/2+pan.Y,w,h);if(Checkerboard){RectangleF visible=RectangleF.Intersect(rect,ClientRectangle);using(Brush light=new SolidBrush(Color.White))using(Brush dark=new SolidBrush(Color.FromArgb(215,220,228))){e.Graphics.FillRectangle(light,visible);GraphicsState state=e.Graphics.Save();e.Graphics.SetClip(visible);for(int y=(int)visible.Top;y<visible.Bottom;y+=16)for(int x=(int)visible.Left;x<visible.Right;x+=16)if(((x-(int)visible.Left)/16+(y-(int)visible.Top)/16)%2==0)e.Graphics.FillRectangle(dark,x,y,16,16);e.Graphics.Restore(state);}}e.Graphics.InterpolationMode=factor>=2?InterpolationMode.NearestNeighbor:InterpolationMode.HighQualityBicubic;e.Graphics.PixelOffsetMode=PixelOffsetMode.HighQuality;e.Graphics.DrawImage(Image,rect);}
 protected override void OnMouseWheel(MouseEventArgs e){if(Image!=null)ZoomAt(EffectiveZoom*(e.Delta>0?1.25:.8),e.Location);base.OnMouseWheel(e);}
 protected override void OnMouseDown(MouseEventArgs e){Focus();if(e.Button==MouseButtons.Left && Image!=null){dragging=true;dragStart=e.Location;dragPan=pan;Capture=true;Cursor=Cursors.SizeAll;}base.OnMouseDown(e);}
 protected override void OnMouseMove(MouseEventArgs e){if(dragging){pan=new PointF(dragPan.X+e.X-dragStart.X,dragPan.Y+e.Y-dragStart.Y);Changed();}base.OnMouseMove(e);}
 protected override void OnMouseUp(MouseEventArgs e){dragging=false;Capture=false;Cursor=Cursors.Default;base.OnMouseUp(e);}
 protected override void OnMouseDoubleClick(MouseEventArgs e){Fit();base.OnMouseDoubleClick(e);}
 protected override void OnResize(EventArgs e){base.OnResize(e);Changed();}
}
sealed class QueueSession {
 public List<BatchItem> Items=new List<BatchItem>();public string Output="";public bool Jpeg,Convert;public int Edge=1600,Quality=90;
 public void Save(string file){XmlDocument d=new XmlDocument();XmlElement root=d.CreateElement("jingQueue");d.AppendChild(root);root.SetAttribute("version","1");root.SetAttribute("output",Output);root.SetAttribute("jpeg",Jpeg.ToString());root.SetAttribute("convert",Convert.ToString());root.SetAttribute("edge",Edge.ToString());root.SetAttribute("quality",Quality.ToString());foreach(BatchItem i in Items){XmlElement e=d.CreateElement("item");root.AppendChild(e);e.SetAttribute("path",i.Path);e.SetAttribute("bytes",i.Bytes.ToString());e.SetAttribute("modified",i.ModifiedTicks.ToString());e.SetAttribute("state",i.State);e.SetAttribute("dimensions",i.Dimensions);e.SetAttribute("method",i.Method);e.SetAttribute("error",i.Error);e.SetAttribute("output",i.Output);}string temp=file+".tmp-"+Guid.NewGuid().ToString("N");try{d.Save(temp);if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);}finally{if(File.Exists(temp))File.Delete(temp);}}
 static int Number(XmlElement r,string key,int min,int max){int n;if(!Int32.TryParse(r.GetAttribute(key),out n)||n<min||n>max)throw new InvalidDataException("任务参数无效："+key);return n;}
 public static QueueSession Load(string file){XmlReaderSettings settings=new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=32L*1024*1024};XmlDocument d=new XmlDocument();d.XmlResolver=null;using(XmlReader r=XmlReader.Create(file,settings))d.Load(r);XmlElement root=d.DocumentElement;if(root==null||root.Name!="jingQueue"||root.GetAttribute("version")!="1")throw new InvalidDataException("不是受支持的景览队列文件。");QueueSession s=new QueueSession{Output=root.GetAttribute("output"),Jpeg=root.GetAttribute("jpeg")=="True",Convert=root.GetAttribute("convert")=="True",Edge=Number(root,"edge",0,10000),Quality=Number(root,"quality",1,100)};var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(XmlNode node in root.ChildNodes){XmlElement e=node as XmlElement;if(e==null||e.Name!="item")throw new InvalidDataException("队列项目格式无效。");if(s.Items.Count>=10000)throw new InvalidDataException("队列超过 10000 项上限。");string path=e.GetAttribute("path");if(!System.IO.Path.IsPathRooted(path))throw new InvalidDataException("队列文件路径必须为绝对路径。");BatchItem i=new BatchItem(path);if(!seen.Add(i.Path))continue;long bytes,ticks;if(!Int64.TryParse(e.GetAttribute("bytes"),out bytes)||!Int64.TryParse(e.GetAttribute("modified"),out ticks))throw new InvalidDataException("文件记录无效。");i.State=e.GetAttribute("state");i.Method=e.GetAttribute("method");i.Dimensions=e.GetAttribute("dimensions");i.Error=e.GetAttribute("error");i.Output=e.GetAttribute("output");
  if(!File.Exists(i.Path)){i.State="文件缺失";i.Error="源文件已移动或删除，请重新添加。";}
  else if(i.Bytes!=bytes||i.ModifiedTicks!=ticks){i.State="待处理";i.Error="源文件已变更，需要重新检测。";i.Dimensions="";i.Method="";i.Output="";}
  else if(i.State=="处理中"||Array.IndexOf(new[]{"待处理","可预览","已转存","失败","超时","已取消","文件缺失"},i.State)<0){i.State="待处理";i.Error="上次任务未完成，可继续处理。";}
  else if(i.State=="已转存"&&!File.Exists(i.Output)){i.State="待处理";i.Output="";i.Error="转存文件已不存在，需要重新转存。";}
  s.Items.Add(i);
 }return s;}
 public static bool Matches(BatchItem item,string keyword,string status){bool state=status=="全部"||(status=="失败 / 超时"&&(item.State=="失败"||item.State=="超时"||item.State=="文件缺失"))||(status=="未完成"&&item.State!="可预览"&&item.State!="已转存")||(status=="成功"&&(item.State=="可预览"||item.State=="已转存"));return state&&(item.Path+" "+item.Error+" "+item.Method).IndexOf(keyword,StringComparison.OrdinalIgnoreCase)>=0;}
}
