 void SetPreviewBackground(Color color,bool checker){picture.BackColor=color;((ZoomPicture)picture).Checkerboard=checker;picture.Invalidate();}
 void ShowFileInfo(){if(currentFile.Length==0)return;try{FileInfo f=new FileInfo(currentFile);MessageBox.Show("文件："+f.Name+"\r\n路径："+f.FullName+"\r\n大小："+f.Length.ToString("N0")+" 字节\r\n修改时间："+f.LastWriteTime.ToString("yyyy-MM-dd HH:mm:ss")+"\r\n当前预览："+(picture.Image==null?"未加载":picture.Image.Width+" × "+picture.Image.Height)+"\r\n当前预览的尺寸可能是系统缩略图或处理后的尺寸。","图片文件信息");}catch(Exception e){MessageBox.Show(e.Message);}}
 Button Compact(string title,EventHandler action){Button b=SmallButton(title,action);b.AutoSizeMode=AutoSizeMode.GrowAndShrink;b.MinimumSize=new Size(85,33);b.Size=new Size(100,33);return b;}
 void OnImageReady(){((ZoomPicture)picture).Fit();try{string dir=System.IO.Path.GetDirectoryName(currentFile);if(!String.Equals(dir,browseFolder,StringComparison.OrdinalIgnoreCase)||!browseFiles.Contains(currentFile)){browseFiles.Clear();foreach(string f in Directory.GetFiles(dir)){if(BatchTools.Known(f)||String.Equals(f,currentFile,StringComparison.OrdinalIgnoreCase))browseFiles.Add(f);if(browseFiles.Count>=10000)break;}browseFiles.Sort(StringComparer.OrdinalIgnoreCase);browseFolder=dir;}browseIndex=browseFiles.FindIndex(delegate(string f){return String.Equals(f,currentFile,StringComparison.OrdinalIgnoreCase);});browseInfo.Text=(browseIndex+1)+" / "+browseFiles.Count;}catch(Exception e){browseInfo.Text="目录浏览不可用";Append("同目录浏览："+e.Message);}}
 void NavigateImage(int direction){if(UseWaitCursor||browseFiles.Count==0)return;int next=browseIndex+direction;if(next<0||next>=browseFiles.Count){imageInfo.Text=direction<0?"已是本文件夹第一张":"已是本文件夹最后一张";return;}browseIndex=next;OpenImage(browseFiles[next],false);}
 void ZoomView(int direction){ZoomPicture view=(ZoomPicture)picture;if(view.Image!=null)view.SetZoom(view.EffectiveZoom*(direction>0?1.25:.8));}
 QueueSession MakeSession(){return new QueueSession{Items=new List<BatchItem>(queue),Output=outputFolder.Text,Jpeg=outputKind.SelectedIndex==1,Convert=retryConvert,Edge=(int)edgeLimit.Value,Quality=(int)jpegQuality.Value};}
 void QueueChanged(){queueDirty=true;if(batchWorker==null)SaveLastQueue();}
 void SaveLastQueue(){try{MakeSession().Save(System.IO.Path.Combine(Core.Data,"last-queue.jingqueue"));queueDirty=false;}catch(Exception e){Append("队列自动保存失败："+e.Message);}}
 void LoadQueue(string file){if(batchWorker!=null&&batchWorker.IsBusy)return;try{if(!File.Exists(file)){UpdateBatchSummary("没有可恢复的任务记录");return;}QueueSession session=QueueSession.Load(file);queue=session.Items;outputFolder.Text=session.Output;outputKind.SelectedIndex=session.Jpeg?1:0;edgeLimit.Value=session.Edge;jpegQuality.Value=session.Quality;retryConvert=session.Convert;RenderQueue();QueueChanged();UpdateBatchSummary("队列已载入；未完成项可继续处理");SelectPage("批量工作台");}catch(Exception e){MessageBox.Show(e.Message,"载入失败，原队列保留");}}
 void FilterQueue(){if(queueSearch==null||queueState==null)return;batchGrid.CurrentCell=null;foreach(DataGridViewRow row in batchGrid.Rows)row.Visible=QueueSession.Matches((BatchItem)row.Tag,queueSearch.Text,queueState.Text.Length==0?"全部":queueState.Text);}
 void ConvenienceUiTests(List<string> lines,string folder){string file=System.IO.Path.Combine(folder,"saved-task.jingqueue");MakeSession().Save(file);int originalCount=queue.Count;queue.Clear();RenderQueue();LoadQueue(file);if(queue.Count!=originalCount)throw new Exception("Queue restoration failed");lines.Add("PASS UI queue save / restore with export settings");queueState.SelectedIndex=3;int visible=0;foreach(DataGridViewRow row in batchGrid.Rows)if(row.Visible)visible++;if(visible!=1)throw new Exception("Result filter did not isolate damaged file");queueState.SelectedIndex=0;lines.Add("PASS UI failure result filter");ZoomPicture view=(ZoomPicture)picture;view.SetZoom(2);if(Math.Abs(view.EffectiveZoom-2)>.001)throw new Exception("Zoom failed");view.ZoomAt(4,new Point(20,20));if(view.PanOffset==PointF.Empty)throw new Exception("Zoom anchor not preserved");view.Fit();if(!view.IsFit)throw new Exception("Fit failed");lines.Add("PASS UI zoom / anchor / fit");
  string original=currentFile,next=System.IO.Path.Combine(folder,"设计预览2.png");using(Bitmap b=new Bitmap(50,30)){b.Save(next,ImageFormat.Png);}browseFolder="";OnImageReady();NavigateImage(1);WaitForUi(delegate{return UseWaitCursor;});if(currentFile!=next)throw new Exception("Next image failed");NavigateImage(-1);WaitForUi(delegate{return UseWaitCursor;});if(currentFile!=original)throw new Exception("Previous image failed");lines.Add("PASS UI same-folder previous / next image");
  SelectPage("批量工作台");string completedOutput=queue[0].Output;StartBatch(true,false,true);WaitForUi(delegate{return batchWorker!=null;});if(queue[0].Output!=completedOutput||queue[1].State!="失败")throw new Exception("Continue repeated completed output");lines.Add("PASS UI continue skips successful items");batchGrid.ClearSelection();batchRows[queue[0]].Selected=true;int count=Directory.GetFiles(outputFolder.Text).Length;StartBatch(true,false,false,true);WaitForUi(delegate{return batchWorker!=null;});if(Directory.GetFiles(outputFolder.Text).Length!=count+1)throw new Exception("Selected export mismatch");lines.Add("PASS UI export selected item only");
 }
 void WaitForUi(Func<bool> pending){System.Diagnostics.Stopwatch watch=System.Diagnostics.Stopwatch.StartNew();while(pending()){Application.DoEvents();System.Threading.Thread.Sleep(10);if(watch.ElapsedMilliseconds>65000)throw new TimeoutException("UI test wait timed out");}}
 // Release dynamic tab descendants before their containers, so disposal cannot
 // recreate handles for an inactive page while its parent is being destroyed.
 void DisposeDescendants(Control root){root.SuspendLayout();Control[] children=new Control[root.Controls.Count];root.Controls.CopyTo(children,0);foreach(Control child in children){if(child is Panel||child is TabControl||child is TabPage)DisposeDescendants(child);ContextMenuStrip menu=child.ContextMenuStrip;child.ContextMenuStrip=null;if(menu!=null)menu.Dispose();child.Dispose();}}
}
static class ConvenienceTests {
 public static void Run(Action<string,Action> test,string temp){
  test("Queue session restores settings and preserves completed output",delegate{string file=System.IO.Path.Combine(temp,"session.jingqueue"),input=System.IO.Path.Combine(temp,"sample.png"),output=System.IO.Path.Combine(temp,"resize.png");QueueSession s=new QueueSession{Output=temp,Jpeg=true,Convert=true,Edge=800,Quality=82};s.Items.Add(new BatchItem(input){State="已转存",Output=output,Dimensions="3 × 2"});s.Save(file);QueueSession restored=QueueSession.Load(file);if(restored.Items[0].State!="已转存"||restored.Edge!=800||!restored.Jpeg||!restored.Convert||restored.Quality!=82)throw new Exception("Session mismatch");});
  test("Queue restores interrupted jobs and detects missing / changed inputs",delegate{string input=System.IO.Path.Combine(temp,"session-source.png"),file=System.IO.Path.Combine(temp,"changed.jingqueue");File.WriteAllText(input,"first");QueueSession s=new QueueSession();s.Items.Add(new BatchItem(input){State="处理中"});s.Save(file);if(QueueSession.Load(file).Items[0].State!="待处理")throw new Exception("Interrupted state");File.WriteAllText(input,"a changed input with different length");if(QueueSession.Load(file).Items[0].State!="待处理")throw new Exception("Changed source");File.Delete(input);if(QueueSession.Load(file).Items[0].State!="文件缺失")throw new Exception("Missing source");});
  test("Queue rejects invalid XML and parameters",delegate{string file=System.IO.Path.Combine(temp,"invalid.jingqueue");File.WriteAllText(file,"<!DOCTYPE jingQueue [<!ENTITY x 'x'>]><jingQueue version='1' edge='0' quality='90'>&x;</jingQueue>");bool blocked=false;try{QueueSession.Load(file);}catch(XmlException){blocked=true;}if(!blocked)throw new Exception("DTD allowed");File.WriteAllText(file,"<jingQueue version='1' edge='99999999' quality='90'/>");blocked=false;try{QueueSession.Load(file);}catch(InvalidDataException){blocked=true;}if(!blocked)throw new Exception("Invalid size allowed");});
  test("Queue status and keyword filtering",delegate{BatchItem i=new BatchItem(System.IO.Path.Combine(temp,"sample.png")){State="超时",Error="decoder timeout"};if(!QueueSession.Matches(i,"TIMEOUT","失败 / 超时")||QueueSession.Matches(i,"timeout","成功")||QueueSession.Matches(i,"missing term","全部"))throw new Exception("Filter mismatch");});
 }
}
